<?php
require dirname(__DIR__).'/includes/functions.php'; if(admin()) go('admin/index.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); try { rate_limit('admin-login',10); $a=one('SELECT * FROM admins WHERE email=?',[post('email')]); if(!$a || !password_verify(post('password'),$a['password'])) throw new DomainException('Invalid administrator credentials.'); session_regenerate_id(true); $_SESSION['admin_id']=$a['id']; $_SESSION['admin_auth']=hash('sha256',$a['password']); $_SESSION['csrf']=bin2hex(random_bytes(32)); go($a['must_change_password']?'admin/password.php':'admin/index.php'); } catch(DomainException $ex) { $error=$ex->getMessage(); } }
$title='Admin sign in'; require ROOT.'/includes/header.php'; ?>
<div class="auth-card glass mx-auto my-5"><p class="eyebrow">STORE CONTROL</p><h1>Admin <span class="gradient-text">access.</span></h1><p>Sign in with your administrator account.</p><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf() ?><label>Email<input name="email" type="email" autocomplete="username" class="form-control" required></label><label>Password<input name="password" type="password" autocomplete="current-password" class="form-control" required></label><button class="btn btn-accent w-100">Sign in to dashboard ↗</button></form></div><?php require ROOT.'/includes/footer.php'; ?>
